<script setup>
import {computed,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {findMovie,pick,movies} from '../data/movies'
import {useMoviesStore} from '../stores/movies'
import '../assets/styles/views.css'
const store=useMoviesStore(),route=useRoute(),router=useRouter(),tab=ref('affinity')
const movie=computed(()=>findMovie(route.params.id))
const results=computed(()=> (tab.value==='affinity'?pick(2,4,12,5,15,16):movies.filter(m=>m.genre===movie.value?.genre)).filter(m=>m.id!==movie.value?.id))
</script>
<template><div v-if="movie" class="view"><button class="back" @click="router.push(`/app/movies/${movie.id}`)">← Volver al detalle</button><div class="view-heading"><h1>Porque te interesó {{movie.title}}</h1></div><section class="panel movie-row"><div class="row-poster" :style="{backgroundImage:movie.gradient}">{{movie.posterTitle}}</div><div class="row-copy"><h2>{{movie.title}}</h2><div class="chips"><span class="chip outline">{{movie.genre}}</span><span class="chip outline">{{movie.year}}</span></div></div></section><h2>Películas que podrían gustarte</h2><div class="chips"><button class="chip" :class="{active:tab==='affinity'}" @click="tab='affinity'">Usuarios con gustos similares</button><button class="chip" :class="{active:tab==='genre'}" @click="tab='genre'">Por género</button></div><div class="row-stack"><article v-for="m in results" :key="m.id" class="movie-row"><button class="row-poster" :style="{backgroundImage:m.gradient,border:0,color:'white'}" @click="router.push(`/app/movies/${m.id}`)">{{m.posterTitle}}</button><div class="row-copy"><RouterLink :to="`/app/movies/${m.id}`"><h3>{{m.title}}</h3></RouterLink><p>{{m.genre}}</p><div class="actions"><span class="rating-text">★ {{m.rating}}</span><span class="muted">{{m.year}}</span></div><p>{{tab==='genre'?'Género compartido: '+m.genre:'Afinidad de ejemplo'}}</p></div><button class="btn-secondary" :aria-label="store.savedIds.includes(m.id)?'Quitar de mi lista':'Guardar en mi lista'" @click="store.toggleSave(m)">{{store.savedIds.includes(m.id)?'✓':'+'}}</button></article><p v-if="!results.length" class="muted">No hay recomendaciones disponibles en el catálogo de prueba.</p></div></div><div v-else class="view"><h1>Película no encontrada</h1><RouterLink to="/app/discover">Volver al catálogo</RouterLink></div></template>
